use vstd::prelude::*;

verus! {

/// Specification-level projection: imaginary part of a complex pair.
spec fn imag_part(z: (f64, f64)) -> f64 {
    z.1
}

/// Return a vector containing the imaginary parts of the input complex numbers.
fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        // Length preserved
        out@.len() == val@.len(),

        // Elementwise mapping: out[i] is the imaginary part of val[i]
        forall|i: int|
            0 <= i < val@.len() ==> out@[i] == imag_part(val@[i]),

        // If the imaginary part is 0.0, output is 0.0 at that index
        forall|i: int|
            0 <= i < val@.len() && val@[i].1 == 0.0 ==> out@[i] == 0.0,

        // If the input complex number is not zero, output equals imaginary part
        forall|i: int|
            0 <= i < val@.len()
            && (val@[i].0 != 0.0 || val@[i].1 != 0.0)
            ==> out@[i] == val@[i].1,
{
    let n: usize = val.len();
    let mut out: Vec<f64> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == val@.len(),
            i <= n,
            out@.len() == i as int,
            forall|j: int| 0 <= j < i as int ==> out@[j] == imag_part(val@[j]),
        decreases n - i,
    {
        let z = val[i];
        out.push(z.1);
        i = i + 1;
    }

    out
}

} // verus!

